import os, re, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from shots import run, BASE, OUT, FIX

# Oisin's round seven, 17 Nov (decisions 89 to 94): overtime at time and a half or double time,
# carried through; an optional note with every no; an email put under a label leaves the Inbox,
# as in Gmail; files on a new email; Roles and access as ticks, after an earlier app of his; and
# Site access, where the managing director picks who runs each site.
results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def go(page, path, sel="main h1"):
    page.goto(BASE + path); page.wait_for_selector(sel); page.wait_for_timeout(500)
def as_role(page, name):
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name=name).click(); page.wait_for_timeout(500)
def toast(page):
    return page.locator("[aria-live=polite]").last.inner_text()
def reset(page):
    page.get_by_role("button", name="Account menu").click(); page.get_by_role("menuitem", name="Reset demo data").click()
    page.get_by_role("button", name="Reset demo data").click(); page.wait_for_timeout(400)
# Anything inside the page that would need dragging sideways to read, or is cut off at the side.
SCROLLS = "[...document.querySelectorAll('main *')].filter(e => e.tagName !== 'NAV' && e.clientWidth > 0 && e.scrollWidth > e.clientWidth + 1 && getComputedStyle(e).overflowX !== 'visible').length"
num = lambda t: 0.0 if t.strip() in ("-", "") else float(t.replace(",", ""))

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main")
    dlg = lambda: page.locator("dialog[open]").last
    reset(page)
    day = data(page, "day")

    # ── 1. Overtime: time and a half and double time. Since round nine (decision 100) a day can
    # hold hours at both rates, typed in two boxes, and an early start is no longer overtime.
    go(page, "/people/timesheet?site=pr-C722", "table")
    opts = page.get_by_label("Today for Adrian Stoica").locator("option").all_inner_texts()
    check("Timesheet: marking overtime is one choice, with the hours at each rate typed beside it", opts == ["Not marked", "Full day", "Half day", "Full + overtime"], opts)
    rules = page.get_by_role("region", name="Overtime rates")
    rt = rules.inner_text()
    check("Timesheet: a note of the overtime rates, with the double time cases as Oisin gave them", all(x in rt for x in ["Double time", "After midnight, when the work carries on from the day before", "Saturday after 12 noon", "Sunday", "Bank holidays", "Time and a half", "Saturday, 8am to 12 noon"]) and "Midnight to 8am" not in rt, rt)
    def type_in(box, text):
        box.click(); box.press("ControlOrMeta+a"); page.keyboard.type(text, delay=40); page.wait_for_timeout(200)
    page.get_by_label("Today for Krzysztof Nowicki").select_option("overtime"); page.wait_for_timeout(150)
    type_in(page.get_by_label("Hours at time and a half for Krzysztof Nowicki"), "4"); type_in(page.get_by_label("Hours at double time for Krzysztof Nowicki"), "2")
    page.get_by_label("Today for Adrian Stoica").select_option("overtime"); page.wait_for_timeout(150)
    type_in(page.get_by_label("Hours at time and a half for Adrian Stoica"), "1.5")
    t = data(page, "db.attendance.filter(a => a.projectId==='pr-C722' && a.date===day).map(a => [db.people.find(p=>p.id===a.personId).name, a.status, a.overtimeHours, a.doubleHours ?? 0]).sort()")
    check("Timesheet: double time is kept beside the time and a half, which needs nothing extra", t == [["Adrian Stoica", "full", 1.5, 0], ["Krzysztof Nowicki", "full", 4, 2]], t)
    check("Timesheet: the choice reads back as marked", page.get_by_label("Today for Krzysztof Nowicki").input_value() == "overtime" and page.get_by_label("Hours at double time for Krzysztof Nowicki").input_value() == "2" and page.get_by_label("Today for Adrian Stoica").input_value() == "overtime")
    box = page.get_by_label("Today for Krzysztof Nowicki").bounding_box()
    check("Timesheet: the choice is not cut off beside its two hours boxes", box and box["width"] >= 120, box)
    page.screenshot(path=f"{OUT}/700-timesheet-overtime.png", full_page=True)
    page.get_by_role("button", name="Send today's time stamps").click(); page.wait_for_timeout(300)
    row = lambda n: page.locator("tbody tr", has_text=n).first.inner_text()
    check("Timesheet: once sent, the day shows the hours at each rate", "Full +4h x1.5 +2h x2" in row("Krzysztof Nowicki") and "Full +1.5h x1.5" in row("Adrian Stoica"), row("Krzysztof Nowicki"))
    # Correcting an earlier day to hours at both rates.
    page.get_by_role("button", name=re.compile("^Cormac Hession, ")).first.click(); page.wait_for_timeout(250)
    d = dlg()
    check("Correction: the same one overtime choice", [o for o in d.get_by_label("Should be").locator("option").all_inner_texts() if "+" in o] == ["Full + overtime"])
    d.get_by_label("Should be").select_option("overtime"); page.wait_for_timeout(150)
    type_in(d.get_by_label("Hours at time and a half"), "5"); type_in(d.get_by_label("Hours at double time"), "3")
    d.get_by_label("Reason for the correction").fill("Pour ran on until after midnight")
    d.get_by_role("button", name="Save correction").click(); page.wait_for_timeout(300)
    ch = data(page, "db.attendanceChanges[0]")
    check("Correction: the change records the hours at each rate", ch and ch["to"] == "Full +5h x1.5 +3h x2" and ch["reason"] == "Pour ran on until after midnight", ch)

    go(page, "/people/history", "table"); page.get_by_role("tablist", name="Attendance layout").get_by_role("tab", name="Everyone").click(); page.wait_for_timeout(300)  # opens per site since round ten
    heads = page.locator("thead th").all_inner_texts()
    check("History: overtime in two columns, time and a half and double time", heads[-4:] == ["Basic hours", "Overtime x1.5", "Overtime x2", "Total hours"], heads)
    tot = data(page, "(() => { const m = day.slice(0,7); const rows = db.attendance.filter(a => a.date.startsWith(m) && a.date <= day); const kn = rows.filter(a => a.personId === db.people.find(p => p.name==='Krzysztof Nowicki').id); const half = (r) => r.reduce((n,a) => n + a.overtimeHours, 0); const dbl = (r) => r.reduce((n,a) => n + (a.doubleHours ?? 0), 0); return { kn15: half(kn), kn2: dbl(kn), all15: half(rows), all2: dbl(rows) } })()")
    r = row("Krzysztof Nowicki").split("\t")
    check("History: Krzysztof's double time is under x2, apart from his time and a half", num(r[-2]) == tot["kn2"] and tot["kn2"] >= 2 and num(r[-3]) == tot["kn15"] and tot["kn15"] >= 4, (r, tot))
    foot = main.locator("tfoot tr").inner_text().split("\t")
    check("History: the totals carry both rates and add up to the hours worked", num(foot[-3]) == tot["all15"] and num(foot[-2]) == tot["all2"] and tot["all2"] > 2 and abs(num(foot[-1]) - (num(foot[-4]) + num(foot[-3]) + num(foot[-2]))) < 0.01, (foot, tot))
    page.get_by_label("Period").select_option("last-week"); page.wait_for_timeout(300)
    page.get_by_label("Site").select_option(label=[o for o in page.get_by_label("Site").locator("option").all_inner_texts() if o.startswith("C724")][0]); page.wait_for_timeout(300)
    c724 = {x.split("\t")[0].split("\n")[0]: x.split("\t") for x in page.locator("tbody tr").all_inner_texts()}
    night = {n: (num(x[-3]), num(x[-2])) for n, x in c724.items() if num(x[-2]) > 0}
    check("History: Derrybawn Bridge's early starts are not overtime now; its double time is the night past midnight and the Saturday afternoon", night == {"Orla Prunty": (11.5, 3.5), "Seán Dunphy": (11.5, 3.5)}, night)
    page.get_by_role("tablist", name="History view").get_by_role("tab", name="Day by day").click(); page.wait_for_timeout(300)
    check("History, day by day: each day's overtime says its hours at each rate", "Full +7.5h x1.5 +1.5h x2" in main.inner_text() and "4h x1.5 + 2h x2" in main.inner_text(), main.inner_text()[:200])
    page.get_by_role("tablist", name="Attendance layout").get_by_role("tab", name="Per site").click(); page.wait_for_timeout(200)
    page.get_by_role("tablist", name="History view").get_by_role("tab", name="Totals for payroll").click(); page.wait_for_timeout(300)
    check("History, per site: the same two overtime columns", main.locator("table").first.locator("thead th").all_inner_texts()[-3:] == ["Overtime x1.5", "Overtime x2", "Total hours"])
    check("History: nothing scrolls sideways with the extra column", page.evaluate(SCROLLS) == 0)
    page.screenshot(path=f"{OUT}/701-history-overtime.png", full_page=True)

    go(page, "/people/payroll", "table")
    heads = page.locator("thead th").all_inner_texts()
    check("Payroll: hours at each rate, side by side", "Overtime x1.5" in heads and "Overtime x2" in heads, heads)
    pre = page.locator("pre").inner_text()
    lines = pre.strip().split("\n")
    check("Payroll: the file for Sage has a column for each rate", lines[0].strip() == "Employee No,Surname,Forename,Period end,Basic hours,Overtime hours x1.5,Overtime hours x2" and all(len(l.split(",")) == 7 for l in lines[1:]) and any(float(l.split(",")[6]) > 0 for l in lines[1:]) and any(float(l.split(",")[5]) > 0 for l in lines[1:]), lines[:3])
    check("Payroll: fits the page", page.evaluate(SCROLLS) == 0)

    # On the site manager's phone
    go(page, "/site")
    page.get_by_role("tab", name="Site manager").click(); page.wait_for_timeout(300)
    page.get_by_label("Site manager to view the phone as").select_option(label="Eoin Brosnan"); page.wait_for_timeout(300)
    page.get_by_role("list", name="My jobs").get_by_role("button").first.click(); page.wait_for_timeout(250)
    page.get_by_label("Phone screen").get_by_role("button", name="Timesheet", exact=True).click(); page.wait_for_timeout(250)
    d = dlg()
    people = d.get_by_role("list", name="People on site today").locator("> li")
    who = data(page, "db.people.find(p => p.id === db.attendance.find(a => a.projectId==='pr-C719' && a.date===day && a.status==='full' && !a.sent).personId).name")
    li = people.filter(has_text=who)
    check("Phone timesheet: overtime is two boxes of hours, one at each rate, with no rate to pick", li.get_by_label(f"{who} hours at time and a half").count() == 1 and li.get_by_label(f"{who} hours at double time").count() == 1 and li.get_by_role("tablist", name=f"{who} overtime rate").count() == 0)
    type_in(li.get_by_label(f"{who} hours at time and a half"), "2"); type_in(li.get_by_label(f"{who} hours at double time"), "1")
    a = data(page, f"db.attendance.find(a => a.projectId==='pr-C719' && a.date===day && db.people.find(p=>p.id===a.personId).name==={who!r})")
    check("Phone timesheet: hours at both rates are saved from the phone", a["overtimeHours"] == 2 and a.get("doubleHours") == 1 and li.get_by_label(f"{who} hours at double time").input_value() == "1", a)
    page.screenshot(path=f"{OUT}/702-phone-overtime.png")
    page.keyboard.press("Escape"); page.wait_for_timeout(200)

    # ── 2. A note with every no
    reset(page)
    go(page, "/schedule/holiday-requests")
    reqs = page.get_by_role("list", name="Holiday requests", exact=True).locator("> li")
    n0 = reqs.count()
    page.get_by_role("button", name="Decline leave for Paudie Lyne").click(); page.wait_for_timeout(250)
    d = dlg()
    check("Leave: Decline asks first, with a note that is optional", d.locator("h2").inner_text() == "Decline leave for Paudie Lyne?" and d.get_by_label("Note (optional)").count() == 1 and "Paudie sees it" in d.inner_text() and d.get_by_role("button", name="Decline leave").is_enabled())
    page.screenshot(path=f"{OUT}/703-decline-note.png")
    d.get_by_role("button", name="Cancel").click(); page.wait_for_timeout(250)
    check("Leave: Cancel leaves the request waiting", reqs.count() == n0 and data(page, "db.holidays.find(h => h.id==='hol-3').status") == "Requested")
    page.get_by_role("button", name="Decline leave for Paudie Lyne").click(); page.wait_for_timeout(250)
    d = dlg(); d.get_by_label("Note (optional)").fill("Scaffold strike that day, everyone is needed")
    d.get_by_role("button", name="Decline leave").click(); page.wait_for_timeout(300)
    hol = data(page, "db.holidays.find(h => h.id==='hol-3')")
    check("Leave: the note is kept with the no, and who gave it", hol["status"] == "Declined" and hol["declineNote"] == "Scaffold strike that day, everyone is needed" and hol["decidedBy"] == "Aidan King" and "with your note" in toast(page), hol)
    dec = page.get_by_role("list", name="Declined holiday requests")
    check("Leave: declined requests stay in view with the note", reqs.count() == n0 - 1 and "Paudie Lyne" in dec.inner_text() and "Note: Scaffold strike that day, everyone is needed" in dec.inner_text() and "Declined by Aidan King" in dec.inner_text() and "João Teixeira" in dec.inner_text(), dec.inner_text())
    check("Leave: the note is in the activity log", data(page, "db.activity[0]")["what"] == "Declined leave" and "Note: Scaffold strike" in data(page, "db.activity[0].target"))
    # Without a note, from People.
    go(page, "/people/holidays", "table")
    page.get_by_role("button", name="Decline leave for Sinéad Colgan").click(); page.wait_for_timeout(250)
    dlg().get_by_role("button", name="Decline leave").click(); page.wait_for_timeout(300)
    check("Leave: a no with nothing typed keeps no note", data(page, "(() => { const h = db.holidays.find(h => h.id==='hol-1'); return [h.status, h.declineNote ?? null] })()") == ["Declined", None])
    page.get_by_role("tablist", name="Leave status").get_by_role("tab", name=re.compile("^Declined")).click(); page.wait_for_timeout(300)
    tbl = main.locator("table")
    check("People, Holidays: the Declined list says why each was declined, or that no note was left", "Why it was declined" in tbl.locator("thead").inner_text() and "Scaffold strike that day" in tbl.locator("tr", has_text="Paudie Lyne").inner_text() and "No note left" in tbl.locator("tr", has_text="Sinéad Colgan").inner_text() and "Short notice, and Ardmullen needs the full crew that week" in tbl.locator("tr", has_text="João Teixeira").inner_text(), tbl.inner_text()[:300])
    # The person reads it on their phone.
    go(page, "/site")
    page.get_by_role("tab", name="Operative").click(); page.wait_for_timeout(250)
    page.get_by_label("Operative to view the phone as").select_option(label=[o for o in page.get_by_label("Operative to view the phone as").locator("option").all_inner_texts() if o.startswith("Paudie Lyne")][0]); page.wait_for_timeout(300)
    page.get_by_role("button", name="My profile").click(); page.wait_for_timeout(250)
    mine = dlg().get_by_role("list", name="My holidays").inner_text()
    check("Phone: the operative sees the no and the note under his holidays", "Declined" in mine and "Note: Scaffold strike that day, everyone is needed" in mine, mine)
    page.screenshot(path=f"{OUT}/704-phone-decline-note.png")
    page.keyboard.press("Escape"); page.wait_for_timeout(200)

    # Admin, Requests: site requests, spending and reimbursements.
    go(page, "/admin")
    main.get_by_role("button", name=re.compile("^Decline: 20 m articulated boom lift")).click(); page.wait_for_timeout(250)
    d = dlg()
    check("Admin: declining a request asks the same way", d.locator("h2").inner_text() == "Decline this request?" and "20 m articulated boom lift" in d.inner_text() and d.get_by_label("Note (optional)").count() == 1)
    d.get_by_label("Note (optional)").fill("Use the tower already on site"); d.get_by_role("button", name="Decline", exact=True).click(); page.wait_for_timeout(300)
    rq = data(page, "db.requests.find(r => r.description.startsWith('20 m articulated boom lift'))")
    check("Admin: the note is kept on a site request turned down", rq["decision"] == "Declined" and rq["declineNote"] == "Use the tower already on site", rq)
    main.get_by_role("button", name=re.compile("^Decline: .*drum mixer")).click(); page.wait_for_timeout(250)
    d = dlg(); d.get_by_label("Note (optional)").fill("Borrow the one from Dunmoy first"); d.get_by_role("button", name="Decline", exact=True).click(); page.wait_for_timeout(300)
    main.locator("section", has_text="Reimbursements").get_by_role("button", name=re.compile("^Decline: reimbursement")).first.click(); page.wait_for_timeout(250)
    d = dlg(); d.get_by_label("Note (optional)").fill("No receipt with the claim"); d.get_by_role("button", name="Decline", exact=True).click(); page.wait_for_timeout(300)
    sp = data(page, "db.spendRequests.find(s => s.what.includes('drum mixer'))")
    ex = data(page, "db.expenses.find(x => x.status === 'Declined')")
    check("Admin: and on spending and a reimbursement", sp["status"] == "Declined" and sp["declineNote"] == "Borrow the one from Dunmoy first" and ex["declineNote"] == "No receipt with the claim" and ex["decidedBy"] == "Aidan King", (sp, ex))
    ans = main.locator("section", has_text="Answered in the last two weeks").inner_text()
    check("Admin: each no is under Answered with its note, reimbursements included", all(x in ans for x in ["Note: Use the tower already on site", "Note: Borrow the one from Dunmoy first", "Note: No receipt with the claim", "Reimbursement for"]), ans)
    page.screenshot(path=f"{OUT}/705-admin-answered-notes.png", full_page=True)
    go(page, "/projects/requests", "table")
    page.get_by_role("tab", name=re.compile("^(Done|Dealt with|Closed)")).click(); page.wait_for_timeout(300)
    check("Projects, Requests: the site sees why it was turned down", "Note: Use the tower already on site" in main.locator("tr", has_text="20 m articulated boom lift").inner_text(), main.locator("tr", has_text="20 m articulated boom lift").inner_text())
    owner = data(page, "db.people.find(p => p.id === db.expenses.find(x => x.status === 'Declined').personId)")
    go(page, "/site")
    if owner["kind"] == "Operative":
        page.get_by_role("tab", name="Operative").click(); page.wait_for_timeout(250)
        page.get_by_label("Operative to view the phone as").select_option(label=[o for o in page.get_by_label("Operative to view the phone as").locator("option").all_inner_texts() if o.startswith(owner["name"])][0])
    else:
        page.get_by_role("tab", name="Site manager").click(); page.wait_for_timeout(250)
        page.get_by_label("Site manager to view the phone as").select_option(label=owner["name"])
    page.wait_for_timeout(300)
    # Someone whose own language is not English gets a language switch; put it on English.
    if page.get_by_role("tab", name="English").count(): page.get_by_role("tab", name="English").click(); page.wait_for_timeout(250)
    page.get_by_role("button", name="My profile").click(); page.wait_for_timeout(250)
    claims = dlg().get_by_role("list", name="My reimbursements").inner_text()
    check("Phone: whoever claimed sees the no and the note", "Declined" in claims and "Note: No receipt with the claim" in claims, claims)
    page.keyboard.press("Escape"); page.wait_for_timeout(200)

    # Approvals: discarding a draft.
    go(page, "/dashboard")
    appr = main.locator("section", has_text="Approvals").last
    title = data(page, "db.approvals.find(a => a.id==='ap-1').title")
    appr.get_by_role("button", name=re.compile("^Variation.*cracked quoins")).click(); page.wait_for_timeout(300)
    appr.get_by_role("button", name="Discard").click(); page.wait_for_timeout(250)
    d = dlg()
    check("Approvals: Discard asks first, with an optional note", d.locator("h2").inner_text() == "Discard this draft?" and title in d.inner_text() and d.get_by_label("Note (optional)").count() == 1)
    d.get_by_label("Note (optional)").fill("Client wants it priced again after the survey"); d.get_by_role("button", name="Discard").click(); page.wait_for_timeout(300)
    ap = data(page, "db.approvals.find(a => a.id==='ap-1')")
    check("Approvals: the note is kept on the discarded draft", ap["status"] == "Discarded" and ap["discardNote"] == "Client wants it priced again after the survey" and "with your note" in toast(page), ap)
    appr.get_by_role("tab", name=re.compile("^Done")).click(); page.wait_for_timeout(300)
    check("Approvals: Done shows it with the note", "Note: Client wants it priced again after the survey" in appr.inner_text())
    page.screenshot(path=f"{OUT}/706-approvals-discard-note.png", full_page=True)
    appr.get_by_role("button", name=re.compile("^Variation.*cracked quoins")).click(); page.wait_for_timeout(300)
    appr.get_by_role("button", name="Move back to waiting").click(); page.wait_for_timeout(300)
    check("Approvals: moving it back to waiting drops the note", data(page, "(() => { const a = db.approvals.find(a => a.id==='ap-1'); return [a.status, a.discardNote ?? null] })()") == ["Pending", None])

    # ── 3. Email: under a label, out of the Inbox
    reset(page)
    go(page, "/inbox", "main h1")
    rows = main.locator("ul[aria-label^='Inbox emails'] > li")
    panel = page.get_by_role("navigation", name="Folders and labels")
    count = lambda name: panel.get_by_role("link", name=re.compile(f"^{name}")).inner_text().strip().split("\n")[-1].strip()
    inbox0, unread0 = data(page, "db.mails.filter(m => m.folder==='Inbox').length"), int(count("Inbox"))
    rows.filter(has_text="Eleanor Prendiville").drag_to(panel.get_by_role("link", name=re.compile("^Complaint"))); page.wait_for_timeout(400)
    if data(page, "db.mails.find(m => m.id==='mail-1').folder") == "Inbox":
        rows.filter(has_text="Eleanor Prendiville").drag_to(panel.get_by_role("link", name=re.compile("^Complaint"))); page.wait_for_timeout(400)
    m1 = data(page, "db.mails.find(m => m.id==='mail-1')")
    check("Email: dragged onto a label, the email leaves the Inbox and says so", m1["folder"] == "Filed" and m1["intent"] == "Complaint" and rows.filter(has_text="Eleanor Prendiville").count() == 0 and "Email moved to Complaint, out of the inbox" in toast(page), (m1["folder"], toast(page)))
    check("Email: the Inbox count drops and the label takes the unread email", int(count("Inbox")) == unread0 - 1 and data(page, "db.mails.filter(m => m.folder==='Inbox').length") == inbox0 - 1 and count("Complaint") == "1", (count("Inbox"), count("Complaint")))
    panel.get_by_role("link", name=re.compile("^Archive")).click(); page.wait_for_timeout(300)
    check("Email: it is not in the Archive either", "Eleanor Prendiville" not in main.inner_text())
    panel.get_by_role("link", name=re.compile("^Complaint")).click(); page.wait_for_timeout(300)
    lab = main.locator("ul[aria-label^='Complaint emails'] > li")
    last = lambda t: t.strip().split("\n")[-1].strip()
    still = data(page, "db.mails.filter(m => m.folder==='Inbox' && m.intent==='Complaint').length")
